{
  "research": [
    {
      "id": "R1",
      "title": "Support Request Classification with Sparse Text Baselines",
      "bullets": [
        "Prepared support request text by removing duplicate messages, standardizing category labels, and checking training and evaluation partitions for overlapping records.",
        "Implemented TF-IDF and logistic regression baselines using specified settings, then inspected confusion matrices and documented errors involving closely related request categories."
      ]
    },
    {
      "id": "R2",
      "title": "Sentence Relevance Baselines for Question Answering",
      "bullets": [
        "Prepared question and candidate sentence pairs from supplied documents, preserving relevance annotations and grouping examples by source document for evaluation.",
        "Implemented a TF-IDF cosine similarity baseline for sentence ranking and reviewed retrieved candidates to characterize lexical overlap errors."
      ]
    }
  ],
  "publications": [],
  "work": [
    {
      "id": "W1",
      "title": "Order Documentation and Inventory Support",
      "bullets": [
        "Checked incoming order forms for missing information, organized supporting paperwork, and routed incomplete requests to the appropriate staff members.",
        "Maintained stockroom inventory logs, reconciled delivery slips against received supplies, and prepared routine handover notes for pending orders."
      ]
    }
  ],
  "projects": [
    {
      "id": "T1",
      "title": "Product Review Sentiment Classification",
      "bullets": [
        "Implemented a multinomial naive Bayes baseline for review sentiment classification using token counts and a fixed training and test split.",
        "Compared count and TF-IDF representations under the same evaluation procedure, examining misclassified reviews containing negation or mixed sentiment."
      ]
    },
    {
      "id": "T2",
      "title": "Extractive Summarization with Sentence Similarity",
      "bullets": [
        "Implemented a sentence ranking baseline that selected document sentences by cosine similarity to the document's average TF-IDF vector.",
        "Compared selected sentences with a lead sentence baseline, reviewing summaries for repeated information, missing context, and coverage of central topics."
      ]
    }
  ]
}
